using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerToolType]
public sealed class ApiTools
{
    [McpServerTool, Description("Fetches a post by ID from the external API.")]
    public static async Task<string> GetPost(
        IHttpClientFactory httpClientFactory,
        [Description("The numeric ID of the post to fetch.")] int id)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");
        var response = await client.GetAsync($"posts/{id}");
        response.EnsureSuccessStatusCode();
        var post = await response.Content.ReadFromJsonAsync<JsonElement>();
        return post.ToString();
    }
}

using System.ComponentModel;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;

[McpServerPromptType]
public sealed class SummarizationPrompts
{
    [McpServerPrompt, Description("Generates a prompt that asks for a concise summary of the provided text.")]
    public static IList<PromptMessage> Summarize(
        [Description("The text to summarize.")] string text)
    {
        return
        [
            new()
            {
                Role = Role.User,
                Content = new Content
                {
                    Type = "text",
                    Text = $"Please provide a concise summary of the following text:\n\n{text}"
                }
            }
        ];
    }
}

